<?php
declare(strict_types=1);
$engine=' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci';
$sql=[
    "CREATE TABLE identity_settings (id TINYINT PRIMARY KEY, bootstrapped BOOLEAN NOT NULL DEFAULT FALSE, dummy_hash VARCHAR(255) NOT NULL)$engine",
    "CREATE TABLE identity_users (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, display_name VARCHAR(191) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','DISABLED')), verified_at DATETIME(6) NULL, identity_version INT UNSIGNED NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6))$engine",
    "CREATE TABLE identity_credentials (user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, password_hash VARCHAR(255) NOT NULL, changed_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(user_id) REFERENCES identity_users(id))$engine",
    "CREATE TABLE identity_customers (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, name VARCHAR(191) NOT NULL, currency CHAR(3) CHARACTER SET ascii NOT NULL, mfa_required BOOLEAN NOT NULL DEFAULT FALSE, version INT UNSIGNED NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6))$engine",
    "CREATE TABLE identity_memberships (user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, customer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, is_owner BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY(user_id,customer_id), FOREIGN KEY(user_id) REFERENCES identity_users(id), FOREIGN KEY(customer_id) REFERENCES identity_customers(id))$engine",
    "CREATE TABLE identity_staff (user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, administrative BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(user_id) REFERENCES identity_users(id))$engine",
    "CREATE TABLE identity_roles (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, name VARCHAR(64) NOT NULL UNIQUE, version INT UNSIGNED NOT NULL DEFAULT 1)$engine",
    "CREATE TABLE identity_permissions (code VARCHAR(96) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY)$engine",
    "CREATE TABLE identity_role_permissions (role_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, permission VARCHAR(96) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, PRIMARY KEY(role_id,permission), FOREIGN KEY(role_id) REFERENCES identity_roles(id), FOREIGN KEY(permission) REFERENCES identity_permissions(code))$engine",
    "CREATE TABLE identity_assignments (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, role_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, customer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, FOREIGN KEY(user_id) REFERENCES identity_users(id), FOREIGN KEY(role_id) REFERENCES identity_roles(id), FOREIGN KEY(customer_id) REFERENCES identity_customers(id), KEY ix_assignment_user(user_id,customer_id))$engine",
    "CREATE TABLE identity_grants (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, assignment_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, permission VARCHAR(96) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, customer_scope VARCHAR(36) CHARACTER SET ascii NOT NULL, service_scope VARCHAR(64) CHARACTER SET ascii NOT NULL DEFAULT '', department_scope VARCHAR(64) CHARACTER SET ascii NOT NULL DEFAULT '', FOREIGN KEY(assignment_id) REFERENCES identity_assignments(id), FOREIGN KEY(permission) REFERENCES identity_permissions(code))$engine",
    "CREATE TABLE identity_resource_scopes (service_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, customer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, department_id VARCHAR(64) CHARACTER SET ascii NULL, FOREIGN KEY(customer_id) REFERENCES identity_customers(id))$engine",
    "CREATE TABLE identity_tokens (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, purpose VARCHAR(24) NOT NULL CHECK(purpose IN ('verify','reset','invite')), secret_hash CHAR(64) CHARACTER SET ascii NOT NULL UNIQUE, customer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, role_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, expires_at DATETIME(6) NOT NULL, consumed_at DATETIME(6) NULL, FOREIGN KEY(user_id) REFERENCES identity_users(id), FOREIGN KEY(customer_id) REFERENCES identity_customers(id), FOREIGN KEY(role_id) REFERENCES identity_roles(id))$engine",
    "CREATE TABLE identity_mfa (user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, secret_encrypted TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT FALSE, last_counter BIGINT NOT NULL DEFAULT -1, FOREIGN KEY(user_id) REFERENCES identity_users(id))$engine",
    "CREATE TABLE identity_recovery (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, code_hash CHAR(64) CHARACTER SET ascii NOT NULL, used_at DATETIME(6) NULL, FOREIGN KEY(user_id) REFERENCES identity_users(id), UNIQUE KEY uq_recovery(user_id,code_hash))$engine",
    "CREATE TABLE identity_sessions (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, native_reference CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE, context VARCHAR(8) NOT NULL CHECK(context IN ('admin','client')), identity_version INT UNSIGNED NOT NULL, customer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, mfa_verified BOOLEAN NOT NULL DEFAULT FALSE, verified_at DATETIME(6) NULL, expires_at DATETIME(6) NOT NULL, revoked_at DATETIME(6) NULL, last_seen_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), device_hash CHAR(64) CHARACTER SET ascii NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(user_id) REFERENCES identity_users(id), FOREIGN KEY(customer_id) REFERENCES identity_customers(id), KEY ix_sessions_user(user_id,revoked_at))$engine",
    "CREATE TABLE identity_devices (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, secret_hash CHAR(64) CHARACTER SET ascii NOT NULL UNIQUE, expires_at DATETIME(6) NOT NULL, revoked_at DATETIME(6) NULL, created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(user_id) REFERENCES identity_users(id))$engine",
    "CREATE TABLE identity_api_credentials (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, customer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, secret_hash CHAR(64) CHARACTER SET ascii NOT NULL UNIQUE, scopes LONGTEXT NOT NULL CHECK(JSON_VALID(scopes)), identity_version INT UNSIGNED NOT NULL, expires_at DATETIME(6) NOT NULL, revoked_at DATETIME(6) NULL, last_used_at DATETIME(6) NULL, created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(user_id) REFERENCES identity_users(id), FOREIGN KEY(customer_id) REFERENCES identity_customers(id))$engine",
    "CREATE TABLE identity_impersonations (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, session_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, customer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, target_user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, reason_encrypted TEXT NOT NULL, expires_at DATETIME(6) NOT NULL, ended_at DATETIME(6) NULL, created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(session_id) REFERENCES identity_sessions(id), FOREIGN KEY(customer_id) REFERENCES identity_customers(id), FOREIGN KEY(target_user_id) REFERENCES identity_users(id), KEY ix_impersonation_session(session_id,ended_at))$engine",
    "CREATE TABLE identity_security_events (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, code VARCHAR(64) CHARACTER SET ascii NOT NULL, trace_id CHAR(36) CHARACTER SET ascii NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(user_id) REFERENCES identity_users(id))$engine",
    "CREATE TABLE identity_notifications (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, template VARCHAR(32) NOT NULL, body_encrypted TEXT NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'HELD', created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(user_id) REFERENCES identity_users(id))$engine",
];
$dummy=password_hash(bin2hex(random_bytes(32)),PASSWORD_ARGON2ID,['memory_cost'=>65536,'time_cost'=>3,'threads'=>1]);
$sql[]="INSERT INTO identity_settings (id,dummy_hash) VALUES (1,'$dummy')";
foreach (['identity.users.view','identity.users.manage','identity.customers.view','identity.customers.manage','identity.roles.manage','identity.staff.manage','identity.security.view','identity.impersonate','account.view','account.manage','members.view','members.manage','services.view','billing.view','orders.view','support.view','sessions.manage','keys.manage'] as $permission) {
    $sql[]="INSERT INTO identity_permissions VALUES ('$permission')";
}
foreach (['Super Admin','Yönetici','Destek','Muhasebe','Müşteri Sahibi','Alt Kullanıcı'] as $name) {
    $id=\Hostider\Core\Id::uuid(); $sql[]="INSERT INTO identity_roles VALUES ('$id','$name',1)";
    $permissions=match($name) {
        'Super Admin'=>['identity.users.view','identity.users.manage','identity.customers.view','identity.customers.manage','identity.roles.manage','identity.staff.manage','identity.security.view','identity.impersonate','account.view','account.manage','members.view','members.manage','services.view','billing.view','orders.view','support.view','sessions.manage','keys.manage'],
        'Yönetici'=>['identity.users.view','identity.customers.view','identity.customers.manage','identity.security.view','identity.impersonate','account.view','account.manage','members.view','members.manage','services.view','sessions.manage','keys.manage'],
        'Destek'=>['identity.customers.view','identity.impersonate','account.view','members.view','services.view','support.view','sessions.manage'],
        'Muhasebe'=>['identity.customers.view','account.view','billing.view','orders.view','sessions.manage'],
        'Müşteri Sahibi'=>['account.view','account.manage','members.view','members.manage','services.view','billing.view','orders.view','support.view','sessions.manage','keys.manage'],
        default=>['account.view','services.view','support.view','sessions.manage'],
    };
    foreach ($permissions as $p) { $sql[]="INSERT INTO identity_role_permissions VALUES ('$id','$p')"; }
}
return $sql;
